def moving_average(values, window):
    from collections import deque
    if window <= 0:
        raise ValueError("window must be positive")
    queue, result = deque(), []
    total = 0
    for value in values:
        queue.append(value); total += value
        if len(queue) > window:
            total -= queue.popleft()
        if len(queue) == window:
            result.append(total / window)
    return result

