static bool list_push_front(struct Node **head, int value)
{
    struct Node *node = malloc(sizeof *node);
    if (node == NULL) return false;
    node->value = value;
    node->next = *head;
    *head = node;
    return true;
}

static bool list_pop_front(struct Node **head, int *out)
{
    if (*head == NULL) return false;
    struct Node *node = *head;
    *out = node->value;
    *head = node->next;
    free(node);
    return true;
}

static struct Node *list_find(struct Node *head, int target)
{
    for (struct Node *p = head; p != NULL; p = p->next) {
        if (p->value == target) return p;
    }
    return NULL;
}

static size_t list_length(const struct Node *head)
{
    size_t n = 0;
    for (const struct Node *p = head; p != NULL; p = p->next) {
        ++n;
    }
    return n;
}

static void list_clear(struct Node **head)
{
    struct Node *p = *head;
    while (p != NULL) {
        struct Node *next = p->next;
        free(p);
        p = next;
    }
    *head = NULL;
}

struct Stack {
    int *data;
    size_t size;
    size_t capacity;
};

static bool stack_push(struct Stack *s, int value)
{
    if (s->size == s->capacity) {
        if (!stack_grow(s)) return false;
    }
    s->data[s->size++] = value;
    return true;
}

static bool stack_pop(struct Stack *s, int *out)
{
    if (s->size == 0) return false;
    *out = s->data[--s->size];
    return true;
}

struct Queue {
    int *data;
    size_t capacity;
    size_t head;
    size_t size;
};

static bool queue_push(struct Queue *q, int value)
{
    if (q->size == q->capacity) return false;
    size_t tail = (q->head + q->size) % q->capacity;
    q->data[tail] = value;
    ++q->size;
    return true;
}

static bool queue_pop(struct Queue *q, int *out)
{
    if (q->size == 0) return false;
    *out = q->data[q->head];
    q->head = (q->head + 1) % q->capacity;
    --q->size;
    return true;
}

