    return true;
}

static bool vector_remove_at(struct IntVector *v, size_t index)
{
    if (index >= v->size) return false;
    if (index + 1 < v->size) {
        memmove(&v->data[index],
                &v->data[index + 1],
                (v->size - index - 1) * sizeof v->data[0]);
    }
    --v->size;
    return true;
}

