    return true;
}

static bool read_entire_file(FILE *fp, unsigned char **out, size_t *out_size)
{
    struct Buffer b = {0};
    unsigned char temp[4096];

    for (;;) {
        size_t n = fread(temp, 1, sizeof temp, fp);
        if (n > 0 && !buffer_append(&b, temp, n)) {
            buffer_destroy(&b);
            return false;
        }
        if (n < sizeof temp) {
            if (ferror(fp)) {
                buffer_destroy(&b);
                return false;
            }
            break;
        }
    }

    *out = b.data;
    *out_size = b.size;
    return true;
}

