static bool load_numbers(FILE *fp, struct IntVector *out)
{
    char line[128];

    while (fgets(line, sizeof line, fp) != NULL) {
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] != '\n' && !feof(fp)) {
            int next = fgetc(fp);
            if (next != EOF || ferror(fp)) {
                return false;
            }
        }

        errno = 0;
        char *end;
        long value = strtol(line, &end, 10);
        if (errno == ERANGE || end == line ||
            value < INT_MIN || value > INT_MAX) {
            return false;
        }

        while (isspace((unsigned char)*end)) {
            ++end;
        }
        if (*end != '\0') {
            return false;
        }

        if (!vector_push(out, (int)value)) {
            return false;
        }
    }

    return !ferror(fp);
}

