static bool reserve_for_append(struct Buffer *b, size_t extra)
{
    size_t needed;
    if (!checked_add_size(b->size, extra, &needed)) return false;
    if (needed <= b->capacity) return true;

    size_t cap = b->capacity ? b->capacity : 64;
    while (cap < needed) {
        if (cap > SIZE_MAX / 2) {
            cap = needed;
            break;
        }
        cap *= 2;
    }
    return buffer_reserve(b, cap);
}

static bool read_token(FILE *fp, char *buf, size_t cap)
{
    if (fp == NULL || buf == NULL || cap < 256) {
        return false;
    }

    if (fscanf(fp, "%255s", buf) != 1) {
        return false;
    }

    int ch = fgetc(fp);
    if (ch == EOF) {
        return !ferror(fp);
    }
    if (isspace((unsigned char)ch)) {
        return true;
    }

    do {
        ch = fgetc(fp);
    } while (ch != EOF && !isspace((unsigned char)ch));

    return false;
}

